-- ── Correct the finding raised from the summary ─────────────────────────────
UPDATE nc_capa SET
  severity = 'Minor',
  description = 'ความเข้มของแสงสว่างต่ำกว่าเกณฑ์กฎหมาย 13 จุดจาก 24 จุดตรวจวัด ตามรายงานผลการตรวจวัดและวิเคราะห์สภาวะการทำงาน สสปท. เลขที่ขอรับบริการ 2569/004 (ตรวจวัด 9 มิ.ย. 2569) — แบบใช้สายตามองเฉพาะจุด ไม่ผ่าน 12 จุดจาก 13 จุด ทั้งหมดเป็นโต๊ะทำงานบันทึกเอกสารในสำนักงาน (วัดได้ 105–340 lux จากเกณฑ์ 400–500 lux) และแบบพื้นที่ ไม่ผ่าน 1 จุดจาก 7 จุด คือ จุดแพ็ค 2 (เฉลี่ย 268 lux จากเกณฑ์ 300 lux สาเหตุพบหลอดไฟชำรุด) · เสียง (80.8 dBA) และความร้อน (WBGT 28.1 °C) ผ่านทั้งหมด',
  evidenceRefs = '["ENV0006","ENV0012","ENV0013","ENV0014","ENV0015","ENV0016","ENV0017","ENV0018","ENV0019","ENV0020","ENV0021","ENV0022","ENV0023"]',
  notes = 'บันทึกจากรายงาน สสปท. 2569/004 — ยังไม่ได้วิเคราะห์สาเหตุรากและกำหนดมาตรการแก้ไข รอ QA/HR ดำเนินการ · ยังไม่ได้กำหนดวันแล้วเสร็จ

[แก้ไขการจัดระดับ 02/08/69] เดิมจัดเป็น Major โดยอ้างว่าจุดที่ไม่ผ่านเป็นจุดตรวจพินิจสิ่งแปลกปลอมจึงกระทบ GHP — เหตุผลนั้นไม่ถูกต้อง มาจากการอ่านหน้าสรุปโดยไม่มีรายละเอียด เมื่อได้รายงานครบ 16 หน้าพบว่า จุดใช้สายตาเฉพาะจุดทั้ง 13 จุดเป็นงานบันทึกเอกสารบนโต๊ะสำนักงาน (สำนักงานผลิต · บัญชี/การเงิน · บุคคล · ขาย/การตลาด · หน้าห้องกรรมการผู้จัดการ) ไม่มีจุดใดเป็นสถานีตรวจสอบในสายการผลิต เกณฑ์ 400–500 lux ที่ใช้เป็นเกณฑ์งานเอกสาร จึงเป็นประเด็นอาชีวอนามัยและการปฏิบัติตามกฎหมาย ไม่ใช่ความปลอดภัยอาหาร

จุดเดียวที่เกี่ยวกับความปลอดภัยอาหารคือ จุดแพ็ค 2 (ENV0006) ซึ่งเป็นการวัดแบบพื้นที่ ไม่ผ่านที่ 268 จาก 300 lux สาเหตุระบุชัดว่าหลอดไฟชำรุด แก้ได้ด้วยการเปลี่ยนหลอดเป็น LED — ควรทำก่อนเป็นลำดับแรก ส่วนห้องเสียบและห้องผลิตเองผ่านที่ 325/166 lux

ระดับ Minor (รอ QA ยืนยัน): ไม่เป็นไปตามกฎหมายจริงและต้องแก้ แต่ผลกระทบจำกัดอยู่ที่งานเอกสารในสำนักงาน และ สสปท. ระบุวิธีแก้ไว้ครบทุกจุดแล้ว (เปลี่ยน/เพิ่มหลอด LED · ย้ายตำแหน่งโต๊ะ 4 จุดที่อยู่มุมห้องหรือใต้เครื่องปรับอากาศ)

ข้อเสนอแนะอื่นจาก สสปท. ที่ยังไม่ได้ดำเนินการ: ตรวจสภาพการมองเห็น (Vision test) ของผู้ปฏิบัติงานประจำปี · ตรวจสมรรถนะการได้ยินปีละ 1 ครั้ง · ให้พนักงานสวม PPE ลดเสียงในห้องเสียบและห้องผลิต · ตรวจวัดแสง/เสียง/ความร้อน ปีละ 1 ครั้งตามกฎหมาย',
  modified = strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE id = 'NCR-256908-002';

